        _isInterstitialAdLoaded = false;
        loadInterstitialAd(); // Preload next
        onAdDismissed?.call();
      },
      onAdFailedToShowFullScreenContent: (ad, error) {
        _isShowingAd = false;
        ad.dispose();
        _isInterstitialAdLoaded = false;
        loadInterstitialAd();
        onAdDismissed?.call();
      },
    );

